def parse_duration(text: str) -> float:
    if not text or not text.startswith('P'):
        raise ValueError("Invalid duration format")

    text = text[1:]  # Remove 'P'

    total_seconds = 0.0

    # Split by 'T' to separate date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T', 1)
        if not time_part:
            raise ValueError("T must be followed by at least one time component")
    else:
        date_part = text
        time_part = None

    # Parse date part
    if date_part:
        if 'W' in date_part:
            if 'D' in date_part:
                raise ValueError("Cannot have both W and D")
            # Extract weeks
            parts = date_part.split('W')
            if len(parts) != 2 or parts[1] != '':
                raise ValueError("Invalid week format")
            try:
                weeks = float(parts[0].replace(',', '.'))
            except ValueError:
                raise ValueError("Invalid week value")
            total_seconds += weeks * 7 * 86400
        elif 'D' in date_part:
            # Extract days
            parts = date_part.split('D')
            if len(parts) != 2 or parts[1] != '':
                raise ValueError("Invalid day format")
            try:
                days = float(parts[0].replace(',', '.'))
            except ValueError:
                raise ValueError("Invalid day value")
            total_seconds += days * 86400
        else:
            if date_part:
                raise ValueError("Invalid date format")

    # Parse time part
    if time_part:
        remaining = time_part

        # Hours
        if 'H' in remaining:
            parts = remaining.split('H', 1)
            try:
                hours = float(parts[0].replace(',', '.'))
            except ValueError:
                raise ValueError("Invalid hour value")
            total_seconds += hours * 3600
            remaining = parts[1]

        # Minutes
        if 'M' in remaining:
            parts = remaining.split('M', 1)
            try:
                minutes = float(parts[0].replace(',', '.'))
            except ValueError:
                raise ValueError("Invalid minute value")
            total_seconds += minutes * 60
            remaining = parts[1]

        # Seconds
        if 'S' in remaining:
            parts = remaining.split('S', 1)
            if parts[1] != '':
                raise ValueError("Invalid format after seconds")
            try:
                seconds = float(parts[0].replace(',', '.'))
            except ValueError:
                raise ValueError("Invalid second value")
            total_seconds += seconds
            remaining = ''

        if remaining:
            raise ValueError("Invalid time format")

    if total_seconds == 0:
        raise ValueError("At least one component must be present")

    return total_seconds

