    else:
        date_part = text
        time_part = None

    # Helper to validate and parse a number (non-negative int or decimal)
    # is_last: whether this is the last component (only one allowed to have fraction)
    def parse_number(s, is_last=False):
        if not s:
            raise ValueError("Empty number")
        # Replace comma with dot for decimal separator
        s = s.replace(',', '.')

        # Check format strictly: digits, optionally followed by dot and more digits
        # Must contain at least one digit
        if '.' in s:
            parts = s.split('.')
            if len(parts) != 2:
                raise ValueError(f"Invalid number format: {s}")
            before, after = parts
            # Both parts must have at least one ASCII digit
            if not before or not after:
                raise ValueError(f"Invalid number format: {s}")
            # All characters must be ASCII digits
            if not all(c in '0123456789' for c in before) or not all(c in '0123456789' for c in after):
                raise ValueError(f"Invalid number format: {s}")
            # Fractions only allowed on last component
            if not is_last:
                raise ValueError(f"Fractions only allowed on last component: {s}")
        else:
            # Must be all ASCII digits
            if not s or not all(c in '0123456789' for c in s):
                raise ValueError(f"Invalid number format: {s}")

        try:
            val = float(s)
            if val < 0:
                raise ValueError(f"Negative number not allowed: {s}")
            return val
        except ValueError:
            raise ValueError(f"Invalid number: {s}")

    # Parse date part
    if date_part:
        if 'W' in date_part and 'D' in date_part:
            raise ValueError("Cannot have both W and D")

        if 'W' in date_part:
            # Extract weeks - weeks cannot have a time part
            if time_part:
                raise ValueError("Weeks cannot be combined with time part")
            parts = date_part.split('W')
            if len(parts) != 2 or parts[1] != '':
                raise ValueError("Invalid week format")
            weeks = parse_number(parts[0], is_last=True)
            total_seconds += weeks * 7 * 86400
        elif 'D' in date_part:
            # Extract days
            parts = date_part.split('D')
            if len(parts) != 2 or parts[1] != '':
                raise ValueError("Invalid day format")
            # Days can have fraction only if no time part
            days = parse_number(parts[0], is_last=(time_part is None))
            total_seconds += days * 86400
        else:
            raise ValueError("Invalid date format")

    # Parse time part
    if time_part:
        remaining = time_part
        found_component = False
        last_component_index = -1

        # Find the last component
        for i, char in enumerate(remaining):
            if char in 'HMS':
                last_component_index = i

        # Hours
        if 'H' in remaining:
            parts = remaining.split('H', 1)
            hours = parse_number(parts[0], is_last=(remaining.index('H') == last_component_index))
            total_seconds += hours * 3600
            remaining = parts[1]
            found_component = True

        # Minutes
        if 'M' in remaining:
            parts = remaining.split('M', 1)
            minutes = parse_number(parts[0], is_last=(remaining.index('M') == last_component_index))
            total_seconds += minutes * 60
            remaining = parts[1]
            found_component = True

